source('R/stile.R');source('R/covarianze.R');d<-read.csv('dati/progetti/faithful.csv');s<-read.csv('dati/progetti/piani_ricampionamento/faithful_split.csv');out<-'risultati/P04';dir.create(out,recursive=TRUE,showWarnings=FALSE)
verifica('fedelta alla fonte',nrow(d)==272&&isTRUE(all.equal(d$eruption_min,as.numeric(datasets::faithful$eruptions)))&&isTRUE(all.equal(d$waiting_min,as.numeric(datasets::faithful$waiting))))
verifica('piano completo senza duplicazioni',!anyDuplicated(s$row_id)&&setequal(d$row_id,s$row_id)&&all(s$set%in%c('train','test')))
d<-merge(d,s,by='row_id',sort=TRUE);tr<-d[d$set=='train',];te<-d[d$set=='test',];verifica('separazione 190 e 82',nrow(tr)==190&&nrow(te)==82&&length(intersect(tr$row_id,te$row_id))==0)
salva('P04','F01',ggplot(tr,aes(eruption_min,waiting_min))+geom_point(colour=geo[1],size=2,alpha=.65)+scale_x_continuous(breaks=2:5)+labs(x='Durata eruzione (min)',y='Attesa successiva (min)'))
salva('P04','F02',ggplot(tr,aes(eruption_min))+geom_histogram(breaks=seq(1.5,5.75,.25),fill=geo[1],colour=paper)+scale_x_continuous(breaks=2:5)+labs(x='Durata eruzione (min)',y='Eruzioni nel train'))
fit<-lm(waiting_min~eruption_min,tr);X<-model.matrix(fit);beta<-unname(coef(fit)[2]);ct<-unname(confint(fit)[2,]);V<-hc3_cov(X,resid(fit));c3<-intervallo(beta,sqrt(V[2,2]),188)
verifica('HC3 simmetrica positiva',max(abs(V-t(V)))<1e-10&&min(eigen(V,symmetric=TRUE)$values)>0)
g<-data.frame(eruption_min=seq(min(tr$eruption_min),max(tr$eruption_min),length.out=150));pc<-predict(fit,g,interval='confidence');pp<-predict(fit,g,interval='prediction');gg<-data.frame(g,fit=pc[,1],cl=pc[,2],cu=pc[,3],pl=pp[,2],pu=pp[,3])
verifica('intervallo predittivo piu ampio',all(gg$pl<gg$cl)&all(gg$pu>gg$cu))
salva('P04','F03',ggplot(gg,aes(eruption_min,fit))+geom_ribbon(aes(ymin=pl,ymax=pu),fill=geo[2],alpha=.13)+geom_ribbon(aes(ymin=cl,ymax=cu),fill=geo[1],alpha=.35)+geom_line(colour=geo[1],linewidth=.8)+geom_point(data=tr,aes(eruption_min,waiting_min),inherit.aes=FALSE,size=1.2,alpha=.35)+scale_x_continuous(breaks=2:5)+labs(x='Durata eruzione (min)',y='Attesa (min)'))
rr<-data.frame(stima=fitted(fit),residuo=resid(fit),durata=tr$eruption_min)
salva('P04','F04',ggplot(rr,aes(stima,residuo))+geom_hline(yintercept=0,linetype=2,colour=geo[6])+geom_point(colour=geo[1],size=2,alpha=.65)+labs(x='Attesa stimata (min)',y='Residuo (min)'))
pr<-predict(fit,te,interval='prediction');te$previsto<-pr[,1];te$low<-pr[,2];te$high<-pr[,3];te$coperto<-te$waiting_min>=te$low&te$waiting_min<=te$high;base<-rep(mean(tr$waiting_min),nrow(te));rmse<-function(a,b)sqrt(mean((a-b)^2));mae<-function(a,b)mean(abs(a-b))
metrics<-data.frame(modello=c('Media train','Retta'),RMSE=c(rmse(te$waiting_min,base),rmse(te$waiting_min,te$previsto)),MAE=c(mae(te$waiting_min,base),mae(te$waiting_min,te$previsto)))
salva('P04','F05',ggplot(te,aes(waiting_min,previsto))+geom_abline(slope=1,intercept=0,colour=geo[6],linetype=2)+geom_point(colour=geo[1],size=2.3,alpha=.7)+coord_equal()+scale_x_continuous(breaks=c(50,70,90))+scale_y_continuous(breaks=c(50,70,90))+labs(x='Attesa osservata (min)',y='Attesa prevista (min)'))
salva('P04','F06',ggplot(metrics,aes(modello,RMSE,fill=modello))+geom_col(width=.55)+scale_fill_manual(values=geo[c(2,1)])+guides(fill='none')+labs(x=NULL,y='RMSE sul test (min)'))
tr$gruppo<-factor(tr$eruption_min>=3,levels=c(FALSE,TRUE),labels=c('Durata < 3','Durata ≥ 3'))
sub<-do.call(rbind,lapply(levels(tr$gruppo),function(g){z<-tr[tr$gruppo==g,];f<-lm(waiting_min~eruption_min,z);data.frame(gruppo=g,n=nrow(z),slope=unname(coef(f)[2]))}))
salva('P04','F07',ggplot(tr,aes(eruption_min,waiting_min,colour=gruppo))+geom_point(size=1.8,alpha=.55)+geom_smooth(method='lm',formula=y~x,se=FALSE,linewidth=.9)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=2:5)+labs(x='Durata eruzione (min)',y='Attesa successiva (min)'))
te<-te[order(te$previsto),];te$ordine<-seq_len(nrow(te))
salva('P04','F08',ggplot(te,aes(ordine,previsto))+geom_ribbon(aes(ymin=low,ymax=high),fill=geo[2],alpha=.16)+geom_line(colour=geo[2],linewidth=.8)+geom_point(aes(y=waiting_min,colour=coperto),size=2)+scale_colour_manual(values=c('TRUE'=geo[1],'FALSE'=geo[3]))+guides(colour='none')+scale_x_continuous(breaks=c(1,40,82))+labs(x='Evento ordinato per previsione',y='Attesa (min)'))
comparison<-data.frame(metodo=c('t classico','HC3, t'),stima=beta,low=c(ct[1],c3[1]),high=c(ct[2],c3[2]))
salva('P04','F09',ggplot(comparison,aes(stima,metodo))+geom_errorbarh(aes(xmin=low,xmax=high),height=.18,colour=geo[2],linewidth=.85)+geom_point(colour=geo[1],size=3)+scale_x_continuous(breaks=c(10.2,10.9,11.6),labels=fmt)+labs(x='Pendenza (min/min)',y=NULL))
write.csv(te,file.path(out,'previsioni_test.csv'),row.names=FALSE);write.csv(V,file.path(out,'cov_HC3.csv'),row.names=FALSE);write.csv(sub,file.path(out,'sottogruppi.csv'),row.names=FALSE)
jsonlite::write_json(list(n_train=190,n_test=82,beta=beta,IC_t=ct,IC_HC3=c3,R2=summary(fit)$r.squared,errori=metrics,coperti=sum(te$coperto),copertura=mean(te$coperto),sottogruppi=sub,baseline=mean(tr$waiting_min)),file.path(out,'valori.json'),digits=12,auto_unbox=TRUE,pretty=TRUE)
